/** Entrada de S500L070_VALIDA_CLONING: 26 dígitos empacados (POINTER(A_I_VACLO,4)). */
public record ConsultaClonacion(
        int sistema,          // dígitos 0-3   IDF_I_SISTEMA
        int tipoLlave,        // dígito  4     IDF_I_TIPO_LLA (solo 1 es válido)
        int tipoMedio,        // dígito  5     IDF_I_TIPO_MDA (0 o 1)
        String medioAcceso,   // dígitos 6-17  DDF_I_MDA, 12 dígitos: String para conservar ceros
        int producto,         // dígitos 18-21
        int instrumento) {    // dígitos 22-25

    public static ConsultaClonacion desdeBuffer(byte[] ebcdic) {
        Nibbles n = Nibbles.of(ebcdic);
        return new ConsultaClonacion(n.integer(0, 4), n.integer(4, 1), n.integer(5, 1),
                                     n.digits(6, 12), n.integer(18, 4), n.integer(22, 4));
    }
}

/** Salida: 61 dígitos empacados dentro de A_O_VACLO[0:6] (7 palabras de 12 dígitos). */
public record MedioClonado(
        int sistema, int tipoLlave, int tipoMedio, String medioAcceso,
        int sucPromotora,     // dígitos 18-21  B12P-SUC-PROM
        int producto, int instrumento,
        int moneda,           // dígitos 30-31
        int csi,              // dígitos 33-34  (dígito 32 es FILLER)
        int sucReferencia,    // dígitos 35-38  B12P-SUC-P-REF
        String cliente,       // dígitos 39-50  B12P-NUM-CLIENTE
        int status,           // dígitos 51-52
        LocalDate fechaAlta) {// dígitos 53-60  B12P-FEC-ALTA (formato a confirmar)

    public byte[] aBuffer(int tamanoCaller) {
        Nibbles n = Nibbles.ceros(84);                  // REPLACE ... BY 4"0" FOR SIZE*12
        n.put(0, sistema, 4).put(4, tipoLlave, 1).put(5, tipoMedio, 1).putDigits(6, medioAcceso, 12)
         .put(18, sucPromotora, 4).put(22, producto, 4).put(26, instrumento, 4).put(30, moneda, 2)
         .put(33, csi, 2).put(35, sucReferencia, 4).putDigits(39, cliente, 12).put(51, status, 2)
         .put(53, Fechas.aNumero(fechaAlta), 8);
        return n.toBytes(Math.min(tamanoCaller, 42));  // se copia lo menor entre 42 bytes y el buffer del llamador
    }
}

/** S500L070: servicio de validación de clonación de medio de acceso. Misma interfaz que exportaba la librería. */
@Service
@RequiredArgsConstructor
public class ValidaClonacionService {

    private final ClonacionRepository b12p;   // S500BD04TARJETAS.S500B12PCLONNING, solo lectura

    /**
     * S500L070_VALIDA_CLONING. Devuelve el código de resultado y, solo si es 0, el medio clonado.
     * Antes el llamador recibía el código como valor de la función y los datos en EA_O_VACLON.
     */
    public ResultadoClonacion validaCloning(ConsultaClonacion in) {
        if (in.tipoLlave() != 1) {
            return ResultadoClonacion.error(CodigoClonacion.TIPO_LLAVE_INVALIDO);   // 2
        }
        return consulta(in);                                                       // CONSULTA_CLONING
    }
}

public record ResultadoClonacion(CodigoClonacion codigo, Optional<MedioClonado> medio) {
    static ResultadoClonacion error(CodigoClonacion c) { return new ResultadoClonacion(c, Optional.empty()); }
}

public enum CodigoClonacion {
    OK(0), NO_EXISTE(1), TIPO_LLAVE_INVALIDO(2), TIPO_MEDIO_INVALIDO(3), MEDIO_EN_CERO(4),
    PRODUCTO_EN_CERO(5), INSTRUMENTO_EN_CERO(6), BLOQUEADO_SISTEMA_127(7), ERROR_BASE(10);
    public final int valor;
    CodigoClonacion(int v) { valor = v; }
}
// FREEZE(TEMPORARY) y SHARING = PRIVATE: el bean singleton sin estado sustituye el congelado;
// la procedure solo usa variables locales, así que compartir la instancia es seguro.

/** VALIDA_ENTRADA: el orden de las validaciones define qué código ve el llamador. */
private Optional<CodigoClonacion> validaEntrada(ConsultaClonacion in) {
    if (in.tipoMedio() != 0 && in.tipoMedio() != 1) {
        return Optional.of(CodigoClonacion.TIPO_MEDIO_INVALIDO);                 // 3
    }
    if (new BigInteger(in.medioAcceso()).signum() <= 0) {
        return Optional.of(CodigoClonacion.MEDIO_EN_CERO);                       // 4
    }
    if (in.tipoMedio() == 0) {                                                   // la llave incluye producto
        if (in.producto() <= 0)    return Optional.of(CodigoClonacion.PRODUCTO_EN_CERO);     // 5
        if (in.instrumento() <= 0) return Optional.of(CodigoClonacion.INSTRUMENTO_EN_CERO);  // 6
    }
    return Optional.empty();
}

public interface ClonacionRepository extends Repository<MedioClonadoEntity, Long> {

    /** FIND B12PCSXMDACTO con tipo de medio 0: medio + producto + instrumento. */
    Optional<MedioClonadoEntity> findFirstByMedAccesoAndContCuentAndProductoAndInstrumento(
            int medAcceso, String contCuent, int producto, int instrumento);

    /** FIND B12PCSXMDACTO con tipo de medio 1: solo el medio. */
    Optional<MedioClonadoEntity> findFirstByMedAccesoAndContCuent(int medAcceso, String contCuent);
}

/** BUSCA_B12. */
@Transactional(readOnly = true)                 // OPEN INQUIRY
Either<CodigoClonacion, MedioClonadoEntity> buscaB12(ConsultaClonacion in) {
    try {
        Optional<MedioClonadoEntity> r = (in.tipoMedio() == 0)
                ? b12p.findFirstByMedAccesoAndContCuentAndProductoAndInstrumento(
                        0, in.medioAcceso(), in.producto(), in.instrumento())
                : b12p.findFirstByMedAccesoAndContCuent(in.tipoMedio(), in.medioAcceso());
        return r.<Either<CodigoClonacion, MedioClonadoEntity>>map(Either::right)
                .orElse(Either.left(CodigoClonacion.NO_EXISTE));                // NOTFOUND -> 1
    } catch (DataAccessException e) {
        log.error("S500/L070/002: ERROR DMSII en B12PCSXMDACTO", e);          // hoy no se registra
        return Either.left(CodigoClonacion.ERROR_BASE);                        // 10
    }
}

private final ClonacionProperties props;   // sistema-bloqueo-estatus: 127

/** CONSULTA_CLONING: VALIDA_ENTRADA, BUSCA_B12, VALIDA_STATUS y MUEVE_B12, cada paso solo si va en 0. */
private ResultadoClonacion consulta(ConsultaClonacion in) {
    Optional<CodigoClonacion> invalida = validaEntrada(in);
    if (invalida.isPresent()) return ResultadoClonacion.error(invalida.get());

    var b12 = buscaB12(in);
    if (b12.isLeft()) return ResultadoClonacion.error(b12.getLeft());
    MedioClonadoEntity e = b12.get();

    // VALIDA_STATUS: solo el sistema 127 rechaza medios con estatus 1.
    if (in.sistema() == props.sistemaConValidacionEstatus() && e.getStatus() == 1) {
        return ResultadoClonacion.error(CodigoClonacion.BLOQUEADO_SISTEMA_127);   // 7
    }
    return new ResultadoClonacion(CodigoClonacion.OK, Optional.of(MedioClonado.de(in, e)));   // MUEVE_B12
}

@Configuration
public class ClonacionDataSourceConfig {

    /**
     * PROC_INICIO: OPEN INQUIRY S500BD04TARJETAS al cargar la librería. En Spring la conexión
     * se valida al arrancar; si falla, el contexto no levanta (equivale a MYSELF.STATUS := -1).
     */
    @Bean
    ApplicationRunner verificaBaseTarjetas(DataSource tarjetas) {
        return args -> {
            try (Connection c = tarjetas.getConnection()) {
                c.setReadOnly(true);
                if (!c.isValid(5)) throw new IllegalStateException("S500/L070/002: E>041001< ERROR DMSII");
            }
        };
    }
}
// PROC_FIN (CLOSE S500BD04TARJETAS) lo hace el pool de conexiones al cerrar el contexto.
